import json, jsonschema

SCHEMA = {"type": "object",
          "properties": {"ok": {"type": "boolean"}},
          "required": ["ok"], "additionalProperties": False}

def extract(call_model, prompt, max_attempts=3):
    note = ""
    for attempt in range(1, max_attempts + 1):
        raw = call_model(prompt + note)
        try:
            obj = json.loads(raw)
            jsonschema.validate(obj, SCHEMA)
            return obj
        except json.JSONDecodeError as e:
            err = f"invalid JSON: {e.msg}"
        except jsonschema.ValidationError as e:
            err = e.message
        note = f"\nYour previous reply failed: {err}. Reply again."
    raise RuntimeError(f"gave up after {max_attempts} attempts: {err}")
